import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E4%BD%9C%E6%A5%AD%E3%83%AD%E3%82%B0.html","title":"作業ログ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.66,"words":498},"filePathRelative":"作業ログ.md"}`),a={name:`作業ログ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="作業ログ" tabindex="-1"><a class="header-anchor" href="#作業ログ"><span>作業ログ</span></a></h1><p><a href="./ノート.html">ノート</a>より。（追記：このページの考察のもと、<a href="./slog.html">slog</a>というのを始めてみた。）</p><p>今vcpkgのqt5-webengineのビルドができないか、と色々と試行錯誤していて、そのメモがうまく残せていないなぁ、と思っての考え。</p><p>作業ログを残すにはどういう形式が良いのだろうか？</p><ul><li>kyanny&#39;s blogの以下の二つは似た話に思う <ul><li><a href="https://blog.kyanny.me/entry/2024/10/24/182537#gsc.tab=0" target="_blank" rel="noopener noreferrer">仕事におけるパーソナルナレッジベース構築ファイナル - @kyanny&#39;s blog</a></li><li><a href="https://blog.kyanny.me/entry/2023/07/21/022516#gsc.tab=0" target="_blank" rel="noopener noreferrer">■ - @kyanny&#39;s blog</a></li></ul></li></ul><h2 id="現状は大きなテキストファイル" tabindex="-1"><a class="header-anchor" href="#現状は大きなテキストファイル"><span>現状は大きなテキストファイル</span></a></h2><p>現状は日々の作業記録を書いておくテキストファイルがあって、これに色々書いている。 大体はその日の日付とやった事を箇条書きで書くだけだが、たまにフリーフォーマットで実行したコマンドやその結果などが貼られていたりする。 週単位で区切っていて、さらに月単位で簡単にまとめている。</p><h3 id="大きなテキストファイルの利点、残しやすい" tabindex="-1"><a class="header-anchor" href="#大きなテキストファイルの利点、残しやすい"><span>大きなテキストファイルの利点、残しやすい</span></a></h3><p>大きなテキストファイルに単に書いていく場合、どこに書いたらいいかわからない、とか悩む事はあまり無い。 とりあえず書いておける。 残しておかないものは残らないので、書きやすいのは大きなメリットだ。</p><h3 id="大きなファイルの欠点、みづらい" tabindex="-1"><a class="header-anchor" href="#大きなファイルの欠点、みづらい"><span>大きなファイルの欠点、みづらい</span></a></h3><p>書きやすいメリットと裏表な部分もあるが、書きやすいけれど見づらい。</p><h3 id="大きなファイルの欠点、探しづらい" tabindex="-1"><a class="header-anchor" href="#大きなファイルの欠点、探しづらい"><span>大きなファイルの欠点、探しづらい</span></a></h3><p>今やってるのは以前にも途中までやった作業のはずだが、結構探しづらくて困っている。 適当に検索をしているが、意外とそのワードがたまたま入っていなかったりする。</p><h3 id="大きなファイルの欠点、邪魔になるので書くのに躊躇する" tabindex="-1"><a class="header-anchor" href="#大きなファイルの欠点、邪魔になるので書くのに躊躇する"><span>大きなファイルの欠点、邪魔になるので書くのに躊躇する</span></a></h3><p>書いたものが結構スペースをとってしまって他の項目が見えなくなるので、あんまり長いログとかは貼りたくない、という気持ちが働く。 そうした書くのを躊躇する要因が嫌だ。</p><h2 id="wikiに1-wikinameとして書く" tabindex="-1"><a class="header-anchor" href="#wikiに1-wikinameとして書く"><span>Wikiに1 WikiNameとして書く</span></a></h2><p>アプリ開発などでは、大体そのアプリのWikiNameを作ってそこに作業ログを書いている。<a href="./パオ碁.html">パオ碁</a>とか。</p><h3 id="wikiの利点、他への邪魔にならない" tabindex="-1"><a class="header-anchor" href="#wikiの利点、他への邪魔にならない"><span>Wikiの利点、他への邪魔にならない</span></a></h3><p>大きな1テキストファイルと異なり、WikiはそのWikiNameの外には迷惑をかけないので長いログとか貼るのもそんなに気にならない。</p><h3 id="wikiの欠点、長くなってくるとイマイチ" tabindex="-1"><a class="header-anchor" href="#wikiの欠点、長くなってくるとイマイチ"><span>Wikiの欠点、長くなってくるとイマイチ</span></a></h3><p>長くなってくると書く場所まで移動するのも面倒だし、見るのもイマイチ。</p><h3 id="wikiの欠点、作業のカテゴリが曖昧だとどこに書くか悩む" tabindex="-1"><a class="header-anchor" href="#wikiの欠点、作業のカテゴリが曖昧だとどこに書くか悩む"><span>Wikiの欠点、作業のカテゴリが曖昧だとどこに書くか悩む</span></a></h3><p>qt5-webviewの評価をしていたら、途中からqt5-webengineを試す方がいい気がしてきてqt5-webengineの記録に繋げたい、 みたいな時に微妙。 タイトルを決めるというのは作業ログと相性が悪い部分はあるよなぁ。</p><h2 id="github-issue" tabindex="-1"><a class="header-anchor" href="#github-issue"><span>GitHub issue</span></a></h2><p>作業ログで割と使うものにGitHubのissueがあって、これはかなり良い気がしている。</p><h3 id="issueの良い所、他の邪魔にならない" tabindex="-1"><a class="header-anchor" href="#issueの良い所、他の邪魔にならない"><span>issueの良い所、他の邪魔にならない</span></a></h3><p>長いテキストファイルと違ってこのissueの外には影響が無いので長いログとか貼ってもへっちゃら。</p><h3 id="issueの良い所、見やすい" tabindex="-1"><a class="header-anchor" href="#issueの良い所、見やすい"><span>issueの良い所、見やすい</span></a></h3><p>見た目的にも日付ごとに区切られて、mdでフォーマットもされて、後から見やすい。</p><h3 id="issueの良い所、探しやすい" tabindex="-1"><a class="header-anchor" href="#issueの良い所、探しやすい"><span>issueの良い所、探しやすい</span></a></h3><p>issueは割と探しやすい。時期で眺めても見つけられるしタイトルでもそれなりに探せるし検索でも見つけられる。 この辺は単なるテキストファイルよりも少し支援がある（本文がヒットした時にそのissueのタイトルがすぐにわかる、など）。</p><h3 id="issueの良い所、長くなってきても入力は楽" tabindex="-1"><a class="header-anchor" href="#issueの良い所、長くなってきても入力は楽"><span>issueの良い所、長くなってきても入力は楽</span></a></h3><p>別に長くなっても入力にそんなには困らない。これはWikiより良い所。</p><h3 id="issueの悪い所、issueを建てるのがかったるい" tabindex="-1"><a class="header-anchor" href="#issueの悪い所、issueを建てるのがかったるい"><span>issueの悪い所、issueを建てるのがかったるい</span></a></h3><p>作業を開始する時にissueを立てるのがかったるい。だから立てるのをサボる事もあり、サボったものはどこにも残らないのでこの世から消え去る。</p><h3 id="issueの悪い所、ローカルじゃない" tabindex="-1"><a class="header-anchor" href="#issueの悪い所、ローカルじゃない"><span>issueの悪い所、ローカルじゃない</span></a></h3><p>仕事によってはGitHubでは無い時もある。そして仕事じゃない趣味とかだと、ログに名前とかがパスとして残るのを後悔するのはちょっと嫌だ、という事もある。まぁkarino2とかなのでこのURLと何が違うんだ、という話はあるが。</p><h2 id="なんとなく思う事を書き出す" tabindex="-1"><a class="header-anchor" href="#なんとなく思う事を書き出す"><span>なんとなく思う事を書き出す</span></a></h2><p>GitHub issueはかなり有能。これに近い何かを求めている気がする。</p><p>タイトルはおそらく必要であり、これがGitHub issueの見やすさに貢献している。一方でタイトルはあとから割と変更するのでファイル名にはしたくないか。 タイトルを考えるのがかったるい事はある。</p><p>howm的に<a href="./MDDeck.html">MDDeck</a>にハッシュタグがあればいいのではないか？ただ同じ作業をしている時にいちいち全部にハッシュタグを入れたくは無い気もする。</p><p>他の事をしている時に目に入らない、というのは結構重要に思う。これがあるからissueには長いログとかを気にせずに貼れる。大きいテキストファイルには貼れない。</p><p>大きなテキストファイルのメリットであるVSCodeで書ける、というのは結構大切な気もする。</p><p>なんか特定の作業について書いていくテキストファイルがあって、それがいい感じにタイトル一覧とか検索とかと統合されていればいいかもしれない。 ならば必要なのは日付のファイル名のmdと、先頭のフォーマットが固定されていてスクリプトで整形出来る事か？</p><h3 id="必要なもの" tabindex="-1"><a class="header-anchor" href="#必要なもの"><span>必要なもの</span></a></h3><ul><li>日付のmdを置く場所</li><li>mdの先頭のフォーマットの決定</li><li>タイトル一覧を日付とともにみる方法</li><li>grep結果をタイトルと見る方法</li></ul><p>とりあえずツールなんてなくてもこれをやってみる事は出来るな。やってみよう。</p><p>ディレクトリの名前はslogとする。blogに対抗してSagyouLogという事でslog。えすろぐと読む。</p><p>続きは<a href="./slog.html">slog</a>に書いていく。</p>`,49)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};